    string template, string? repoRoot, IEnvironmentAccessor? env)
{
    var present = new HashSet<string>(StringComparer.Ordinal);
    foreach (var (key, _) in KeyEnvFile.Read(env))
        present.Add(key);
    foreach (var key in new[] { "HF_TOKEN", "DEEPSEEK_API_KEY", "MOONSHOT_API_KEY", "ANTHROPIC_API_KEY", "OPENAI_API_KEY" })
        if (KeyEnvFile.GetEnv(key, env) is not null)
            present.Add(key);

    // ── Zero-key guard ────────────────────────────────────────────
    if (present.Count == 0)
    {
        var keyFilePath = KeyEnvFile.ResolvePathForCurrentUser(env);
        if (File.Exists(keyFilePath))
        {
            // Key file exists — check whether it has keys.
            var fileKeys = KeyEnvFile.Read(env);
            // Only count the five known provider keys
            var providerKeyNames = new[] { "HF_TOKEN", "DEEPSEEK_API_KEY", "MOONSHOT_API_KEY", "ANTHROPIC_API_KEY", "OPENAI_API_KEY" };
            var fileProviderKeys = fileKeys
                .Where(kv => providerKeyNames.Contains(kv.Key))
                .ToList();
            if (fileProviderKeys.Count > 0)
            {
                var keyNames = fileProviderKeys.Select(kv => kv.Key).OrderBy(k => k, StringComparer.Ordinal);
                var summary = $"backend: WARNING — provider key file {keyFilePath} contains {fileProviderKeys.Count} keys " +
                    $"({string.Join(", ", keyNames)}) but detection saw zero keys — environment-resolution failure; using static config";
                return (null, summary);
            }
        }

        return (null, "backend: zero keys — using static config");
    }

    // Load tier model overrides from .relay/config.json.
    IReadOnlyDictionary<string, string>? overrides = null;
    if (repoRoot is not null)
    {
        var configResult = RelayConfigLoader.TryLoadAsync(repoRoot).GetAwaiter().GetResult();
        if (configResult.Status == RelayConfigStatus.Loaded)
            overrides = configResult.Config.TierModelOverrides;
    }

    return BackendConfigGenerator.Generate(present, template, overrides);
}

