using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

/// <summary>
/// Zero-key guard tests for <see cref="BackendConfigStep"/> — the third partial
/// of <see cref="BackendLifecycleStatusTests"/> (sharing its temp-XDG fixture).
/// Covers the three zero-key scenarios: empty present-set with no key file,
/// key file exists but detection sees nothing, and the durable summary line on
/// successful generation.
/// </summary>
public sealed partial class BackendLifecycleStatusTests
{
    // ── Zero-key: flat empty env — falls back to static template ──────────

    [Fact]
    public async Task GenConfig_ZeroKeysNoKeyFile_FallsBackToStaticTemplate_NoGeneratedFileWritten()
    {
        var (repoRoot, template) = WriteStaticTemplate();
        var paths = Paths();
        Directory.CreateDirectory(paths.Scratch);

        // Empty env accessor — no HOME, no provider keys anywhere.
        var env = new DictionaryEnvironmentAccessor();
        var log = new List<string>();

        var config = await BackendConfigStep.ResolveAsync(
            paths, repoRoot, TimeSpan.FromSeconds(10), log.Add, env: env);

        // Must fall back to the static template, not write a degenerate generated file.
        Assert.Equal(template, config);
        Assert.Contains(log, l => l.Contains("zero keys") && l.Contains("static config"));

        // No generated config file on disk.
        Assert.False(File.Exists(paths.GeneratedConfig));
    }

    // ── Zero-key: key file present but detection saw nothing ──────────────

    [Fact]
    public async Task GenConfig_KeyFileExistsButDetectionEmpty_SurfacesAlert()
    {
        var (repoRoot, template) = WriteStaticTemplate();
        var paths = Paths();
        Directory.CreateDirectory(paths.Scratch);

        // Set up a user-level .env that HAS keys...
        var userEnvDir = Path.Combine(_home, ".config", "visual-relay");
        Directory.CreateDirectory(userEnvDir);
        var userEnv = Path.Combine(userEnvDir, ".env");
        await File.WriteAllTextAsync(userEnv, "HF_TOKEN=hf_secret\nDEEPSEEK_API_KEY=ds_secret\n");

        // ...but the env accessor hides them (simulates a path-resolution failure).
        // No HOME set => ResolvePathForCurrentUser falls through to a default that
        // won't find the file in the temp home. The file still exists on disk at
        // the real path, but detection via the accessor sees nothing.
        var env = new DictionaryEnvironmentAccessor();
        // Set HOME to point at the temp home so KeyEnvFile.Read(env) can find
        // the .env file — but this time we DON'T want it to find keys.
        // Actually: let's set HOME to a different directory so KeyEnvFile.Read
        // won't see the file, but we still have the file on disk at a path
        // that ResolvePathForCurrentUser(env) would resolve.
        //
        // Tricky: we need the key file to EXIST on the filesystem (so the
        // guard branch finds it) but KeyEnvFile.Read to return empty (so
        // detection sees zero keys). The cleanest approach: write the key
        // file, set the env accessor's HOME to the temp home, but set
        // XDG_CONFIG_HOME to a bogus subdirectory so ResolvePathForCurrentUser
        // resolves to a path where the file DOES exist — but we'll pre-create
        // it there too.
        var configDir = Path.Combine(_home, ".config", "visual-relay");
        Directory.CreateDirectory(configDir);
        var keyFile = Path.Combine(configDir, ".env");
        await File.WriteAllTextAsync(keyFile, "HF_TOKEN=hf_secret\nDEEPSEEK_API_KEY=ds_secret\n");

        // Now use an env accessor with HOME set so Path resolution works,
        // but NO provider env vars AND KeyEnvFile.Read(env) returns empty
        // (the key file has keys but the accessor has no provider env vars
        //  — wait, KeyEnvFile.Read reads the file off disk, it doesn't go
        //  through the accessor for file contents. It only uses the accessor
        //  for the path resolution. So if HOME is set correctly, Read will
        //  find the file and return keys. That won't work for this test.)
        //
        // Rethinking: the "key file exists but detection empty" scenario
        // happens when KeyEnvFile.Read(env) returns empty because either (a)
        // the file can't be found (path resolution fails) or (b) the file is
        // empty/parsed to nothing. We need case (a): path resolution resolves
        // to a file that exists and has keys, but Read(env) returns empty.
        //
        // The simplest way: write the file, then use an env accessor where
        // HOME is set but XDG_CONFIG_HOME points to a nonexistent dir, so
        // ResolvePath resolves to a nonexistent path. Then Read() returns
        // empty. But ResolvePathForCurrentUser(env) returns the same
        // nonexistent path, so File.Exists would return false.
        //
        // Actually wait: the plan says: "Key file non-empty but detection
        // empty: loud surface triggered." The "key file non-empty" means
        // the .env file physically exists and has keys inside it. But
        // detection (the present-key set built from KeyEnvFile.Read + process
        // env) produces an empty set. How? The Read returns empty because
        // the path it resolves can't find the file (because HOME or
        // XDG_CONFIG_HOME in the accessor doesn't match where the file is
        // on disk). Meanwhile ResolvePathForCurrentUser resolves the same
        // path and also won't find it.
        //
        // Hmm, the guard checks present.Count == 0 AND THEN calls
        // ResolvePathForCurrentUser and checks File.Exists. If the path
        // resolution is consistent between Read and ResolvePathForCurrentUser,
        // File.Exists will also return false.
        //
        // The real scenario from the incident: a transient XDG_CONFIG_HOME/HOME
        // glitch. During one start, HOME isn't set, so both Read and
        // ResolvePathForCurrentUser fail. But the NEXT start has HOME set
        // correctly. The guard detects zero keys at this one start and falls
        // back to the template. The WARNING branch is for when the key file
        // exists but Read returned empty for some OTHER reason.
        //
        // Let me re-read the plan: "If zero AND KeyEnvFile.ResolvePathForCurrentUser()
        // exists AND KeyEnvFile.Read(filePath) is non-empty → loud alert."
        // So it calls Read(filePath) directly (not Read(env)). The file exists,
        // and when read directly from disk returns non-empty keys. But the
        // original Read(env) returned empty. This means path resolution between
        // the two calls differed, or the accessor returned a different path.
        //
        // The simplest way to test this: set up the .env in the default location
        // for the temp HOME, then use an accessor where HOME is set correctly
        // (so Read and ResolvePathForCurrentUser both work). But then Read
        // WOULD return keys and present wouldn't be empty. Hmm.
        //
        // OK, the key insight: ResolvePathForCurrentUser and Read both use the
        // same accessor, so they'll resolve the same path. The only way to get
        // "file exists with keys" but "Read returned empty" is if the file
        // exists on the real filesystem at a path that the accessor doesn't
        // resolve to. But we can't control that with a single accessor.
        //
        // Let me look at this differently. The test should just verify the
        // code branch: if present.Count == 0, the guard checks the file.
        // The test just needs to set up the conditions where:
        // 1. present.Count == 0 (no keys detected via env accessor)
        // 2. The key file path exists on disk with content
        //
        // To achieve this with a DictionaryEnvironmentAccessor: set HOME so
        // Path resolution works AND the file exists there. But then Read(env)
        // would find the file and return keys -> present won't be empty.
        //
        // UNLESS: KeyEnvFile.Read(env) catches InvalidOperationException
        // when ResolvePath throws (e.g., no HOME). But if HOME is set, it
        // won't throw.
        //
        // Actually, let me re-read KeyEnvFile.Read():
        // ```
        // public static Dictionary<string, string> Read(IEnvironmentAccessor? accessor = null)
        // {
        //     try { return Read(ResolvePath(accessor)); }
        //     catch (InvalidOperationException) { return new Dictionary<string, string>(); }
        // }
        // ```
        //
        // It reads via ResolvePath(accessor) which calls ResolvePath(GetEnv("XDG_CONFIG_HOME"), GetEnv("HOME")).
        // If HOME is not set via accessor, ResolveConfigDir throws InvalidOperationException, caught
        // by Read, returning empty.
        //
        // But ResolvePathForCurrentUser(env) uses the SAME accessor:
        // ```
        // public static string ResolvePathForCurrentUser(IEnvironmentAccessor? accessor) =>
        //     ResolvePath(accessor);
        // ```
        // which calls the same ResolvePath(accessor), which calls
        // ResolvePath(GetEnv("XDG_CONFIG_HOME", accessor), GetEnv("HOME", accessor)).
        //
        // So if HOME is not set, BOTH fail the same way. The guard in my
        // code has a try-catch around ResolvePathForCurrentUser, so both
        // return from the catch, entering the "zero keys — using static
        // config" path, not the WARNING path.
        //
        // So the WARNING path really only triggers when the file path
        // resolves (HOME is set) but Read returns empty because the file
        // doesn't exist at that path. But then Read(filePath) in the guard
        // won't find keys either.
        //
        // Hmm, actually I think the WARNING path is for a subtler scenario:
        // The file DOES exist and has keys, but KeyEnvFile.Read(env) returns
        // empty because the env accessor's path resolution finds the
        // file BUT the file parsing returns empty (maybe the file is
        // corrupt/invalid format, or the Read overload that takes a path
        // was used). Wait, let me re-read:
        //
        // ```
        // public static Dictionary<string, string> Read(IEnvironmentAccessor? accessor = null)
        //     => try Read(ResolvePath(accessor)) catch InvalidOperationException => empty dict
        //
        // public static Dictionary<string, string> Read(string filePath)
        //     => if !File.Exists(filePath) return empty; parse...
        // ```
        //
        // So Read(env) and Read(filePath) both go through Read(string).
        // If the file exists and has keys, Read(string) returns them.
        //
        // I think the only real scenario for the WARNING is when the env
        // accessor resolves a DIFFERENT path than the real filesystem. For
        // example, in a sandbox where XDG_CONFIG_HOME is set to a container
        // path that doesn't exist yet, but the real user's .env is at a
        // different location. Or the accessor has a stale HOME.
        //
        // In tests, we can simulate this with a custom IEnvironmentAccessor
        // that returns HOME for path resolution but the file doesn't exist
        // at that path. But then the WARNING path File.Exists check would
        // also fail.
        //
        // I think the correct test setup is:
        // - Write the .env file at the temp home's config dir
        // - Use an accessor that has NO HOME set (so Read returns empty via
        //   InvalidOperationException)
        // - BUT the guard's ResolvePathForCurrentUser(env) ALSO fails
        // - So we get the simple "zero keys" message, not the WARNING
        //
        // To get the WARNING specifically, we need: present == 0, keyFile
        // exists on disk, Read(filePath) returns non-empty. The only way
        // present == 0 AND the file exists is if Read(env) resolved a
        // DIFFERENT path than Read(filePath). But both use the same
        // ResolvePath(env).
        //
        // ...Wait, I'm overcomplicating this. Let me look at the actual
        // guard code in BackendConfigStep.Generate:
        //
        // ```
        // if (present.Count == 0)
        // {
        //     var keyFilePath = KeyEnvFile.ResolvePathForCurrentUser(env);
        //     if (File.Exists(keyFilePath))
        //     {
        //         var fileKeys = KeyEnvFile.Read(env);
        //         ...
        //     }
        //     return (null, "backend: zero keys — using static config");
        // }
        // ```
        //
        // Both ResolvePathForCurrentUser and Read use `env`. If env has no HOME,
        // ResolvePathForCurrentUser throws -> caught, File.Exists never checked.
        // If env has HOME, both resolve the same path. The WARNING can only
        // fire if ResolvePath succeeds AND Read returns empty. This can happen
        // if the file exists at the resolved path but Read returns empty
        // because... the file is empty? No, we check that.
        //
        // Actually, I think there's a subtlety: Read(env) uses
        // ResolvePath(accessor) which calls
        // ResolvePath(GetEnv("XDG_CONFIG_HOME"), GetEnv("HOME")). 
        // ResolvePathForCurrentUser(accessor) calls ResolvePath(accessor)
        // which does the same. So they're identical.
        //
        // The only way to get the WARNING is to have the file exist on disk
        // at the resolved path but Read return no provider keys. That happens
        // when the file exists but has no matching provider key names.
        // But in that case the WARNING would say "contains 0 keys".
        //
        // I think for the test I should just test the "file exists but
        // contains no provider keys" variant, or I need to create a custom
        // IEnvironmentAccessor that gives different answers. Actually, the
        // simpler approach: the test should just verify that when
        // present.Count == 0 AND the key file path resolves to an existing file
        // AND that file has provider keys — but Read(env) returned empty —
        // the WARNING surfaces.
        //
        // To make Read(env) return empty while the file exists AND has keys:
