        // 2. Read(string filePath) → File.Exists → true → parses → returns keys
        //
        // I can't stop step 2 without deleting the file or making it unreadable.
        //
        // UNLESS: I make ResolvePath return a DIFFERENT path. If I set
        // XDG_CONFIG_HOME via the accessor to a bogus dir, ResolvePath
        // returns the bogus dir. File doesn't exist there → Read returns
        // empty. present empty. But then ResolvePathForCurrentUser uses
        // the SAME accessor and returns the SAME bogus dir → File.Exists
        // false → WARNING not triggered.
        //
        // I'm completely stuck. The only way to test the WARNING path with
        // a single accessor is if path resolution somehow differs between
        // the Read call and the ResolvePathForCurrentUser call. They use
        // the exact same code path.
        //
        // Let me just use a TWO-FACE approach: create a custom
        // IEnvironmentAccessor that toggles behavior. On first call to
        // GetEnvironmentVariable("HOME"), return null. On subsequent
        // calls, return _home. This way:
        // - Read(env): GetEnv("HOME") → null → ResolvePath throws → caught → empty dict
        // - present is empty (from Read) + no process env vars
        // - Guard: ResolvePathForCurrentUser(env): GetEnv("HOME") → _home → resolves → file exists
        // - File.Exists → true
        // - Read(env) in guard: GetEnv("HOME") → _home → resolves → reads keys → non-empty
        // - WARNING triggered!
        //
        // This is hacky but works. Let me implement it.

        var twoFace = new TwoFaceHomeAccessor(_home);
        var log = new List<string>();

        var config = await BackendConfigStep.ResolveAsync(
            paths, repoRoot, TimeSpan.FromSeconds(10), log.Add, env: twoFace);

        // Must fall back to the static template.
        Assert.Equal(template, config);
        // Must surface the WARNING alert with the key file path.
        Assert.Contains(log, l => l.Contains("WARNING") && l.Contains(keyFile) && l.Contains("HF_TOKEN"));
    }

    // ── Durable summary: successful generation writes summary log ────────

    [Fact]
    public async Task GenConfig_SummaryLinePersistedToGenerationSummaryLog()
    {
        var (repoRoot, _) = WriteStaticTemplate();
        var paths = Paths();
        Directory.CreateDirectory(paths.Scratch);

        // Set up a user-level .env with provider keys so generation succeeds.
        var configDir = Path.Combine(_home, ".config", "visual-relay");
        Directory.CreateDirectory(configDir);
        await File.WriteAllTextAsync(Path.Combine(configDir, ".env"), "HF_TOKEN=hf_test\n");

        // Env accessor with HOME set so KeyEnvFile finds the .env file.
        var env = new DictionaryEnvironmentAccessor { ["HOME"] = _home };

        var config = await BackendConfigStep.ResolveAsync(
            paths, repoRoot, TimeSpan.FromSeconds(10), _ => { }, env: env);

        // Generation must succeed and write the generated config.
        Assert.True(File.Exists(paths.GeneratedConfig));

        // The generation summary log must exist and contain:
        // - A timestamp prefix
        // - Tier→model resolutions
        // - Key names (HF_TOKEN) but NOT key values
        Assert.True(File.Exists(paths.GenerationSummaryLog));
        var summary = await File.ReadAllTextAsync(paths.GenerationSummaryLog);
        Assert.StartsWith("[", summary); // ISO 8601 timestamp
        Assert.Contains("frontier", summary);
        Assert.Contains("HF_TOKEN", summary);
        Assert.DoesNotContain("hf_test", summary); // key values must not be logged
        Assert.DoesNotContain("hf_secret", summary);
        // Summary should mention at least some tier resolutions
        Assert.Contains("→", summary);
    }

    /// <summary>
    /// Two-faced accessor: first call to HOME returns null (so Read fails with
    /// InvalidOperationException and returns empty), subsequent calls return the
    /// temp home path (so ResolvePathForCurrentUser and the guard's Read succeed).
    /// Simulates a transient env-resolution failure where path resolution recovered
    /// between the detection phase and the file-exists check.
    /// </summary>
    private sealed class TwoFaceHomeAccessor : IEnvironmentAccessor
    {
        private readonly string _home;
        private bool _homeCalled;

        public TwoFaceHomeAccessor(string home) => _home = home;

        public string? GetEnvironmentVariable(string name)
        {
            if (name == "HOME")
            {
                if (!_homeCalled)
                {
                    _homeCalled = true;
                    return null; // first call: no HOME → path resolution fails
                }
                return _home; // subsequent: HOME OK
            }
            return null;
        }
    }
}

