private static async Task<string?> GenerateWithTimeoutAsync(
    BackendPaths paths,
    string template,
    string? repoRoot,
    TimeSpan timeout,
    IEnvironmentAccessor? env,
    Action<string> log,
    CancellationToken cancellationToken)
{
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
    cts.CancelAfter(timeout);

    // Generation is CPU-bound file work; run it on a pool thread so the
    // CancelAfter deadline can abandon a pathological template parse.
    var token = cts.Token;
    var (yaml, summary) = await Task.Run(() => Generate(template, repoRoot, env), token);

    // TODO (stage 6): zero-key guard — when yaml is null (no provider keys
    // detected), log the summary and return null so the caller falls back to
    // the static template. Also persist summary to GenerationSummaryLog.

    Directory.CreateDirectory(paths.Scratch);
    await File.WriteAllTextAsync(paths.GeneratedConfig, yaml!, token);
    return paths.GeneratedConfig;
}

